$ErrorActionPreference = 'Stop'
$root = 'C:/Users/swami/Projects/gct-gpt'
$coord = "$root/work/batch15_workers/B15-12"
$out = "$coord/results/b25_12"
$handover = "$root/Claude_Handover_B15_B18/post_b19_housekeeping_20260917"
$utf8 = New-Object System.Text.UTF8Encoding($false)
function WriteText($path,$value) { [IO.File]::WriteAllText($path,($value -replace "`r`n","`n"),$utf8) }
function Hash($path) { (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant() }
$inventory = Get-Content -Raw "$out/INTAKE_INVENTORY_20260922.json" | ConvertFrom-Json
$files = @($inventory.packets | ForEach-Object { $_.files })
foreach($f in $files) { if((Hash $f.absolute_path) -ne $f.sha256_raw) { throw "Changed since intake: $($f.absolute_path)" }; if($f.hash_match -eq $false -or $f.size_match -eq $false) { throw "Manifest mismatch $($f.path)" } }
$notes = @('A25_INTEGRATOR_VERIFICATION_NOTE.md','A25_05_INTEGRATOR_CHECK_NOTE.md','B25_01_03_INTEGRATOR_COMPILE_NOTE.md','B25_02_INTEGRATOR_COMPILE_NOTE.md')
[IO.Directory]::CreateDirectory("$out/integrator_notes") | Out-Null
$checks = @()
$snapshots = @()
foreach($n in $notes) {
  $source = "$handover/$n"; $dest = "$out/integrator_notes/$n"
  [IO.File]::WriteAllBytes($dest,[IO.File]::ReadAllBytes($source))
  $snapshots += [ordered]@{source=$source; snapshot=$dest; sha256=(Hash $source); identical=((Hash $source) -eq (Hash $dest))}
  $text = [IO.File]::ReadAllText($source)
  foreach($m in [regex]::Matches($text,'\b[0-9a-f]{64}\b')) {
    $h = $m.Value
    $raw = @($files | Where-Object sha256_raw -eq $h)
    $before = @($files | Where-Object before_sha256 -eq $h)
    $checks += [ordered]@{note=$n; cited_sha256=$h; status=$(if($raw.Count){'MATCH_LOCAL_RAW'}elseif($before.Count){'MATCH_COMMITTED_CONTENT'}else{'UNVERIFIED_ARTIFACT_NOT_LOCATED'}); paths=@($raw.absolute_path)+@($before.absolute_path)}
  }
}
$helper = "$handover/a25_05_integrator_check.py"
if(Test-Path -LiteralPath $helper) { [IO.File]::WriteAllBytes("$out/integrator_notes/a25_05_integrator_check.py",[IO.File]::ReadAllBytes($helper)); $snapshots += [ordered]@{source=$helper; snapshot="$out/integrator_notes/a25_05_integrator_check.py"; sha256=(Hash $helper); identical=$true} }
$receipt = [ordered]@{observed_utc=[DateTime]::UtcNow.ToString('s')+'Z'; scope='Read/hash only; evaluator and compiler not run'; notes=$snapshots; cited_full_hashes=$checks; artifact_search='Compile PDFs/logs not found in handover or relevant paper directories; candidate PDFs in Downloads were hash-checked without a matching cited digest. This is not a claim of global absence.'}
WriteText "$out/NOTE_HASH_VERIFICATION_20260922.json" ($receipt | ConvertTo-Json -Depth 12)
$noteLines = @('# Integrator-note intake — 2026-09-22','','All cited full source hashes match local raw files or the recorded committed-content hash. The three cited full PDF hashes remain UNVERIFIED: matching build artifacts were not located. Build outcomes are integrator-reported on matched source bytes, not independently replayed. No mathematical acceptance follows.','','| Note | Cited SHA256 | Verification |','|---|---|---|')
foreach($c in $checks) { $noteLines += "| $($c.note) | ``$($c.cited_sha256)`` | $($c.status) |" }
$noteLines += @('','Four notes are preserved byte-for-byte under integrator_notes/. The A25-05 helper is copied if present, but was not executed. Note hashes and exact source/snapshot paths are in NOTE_HASH_VERIFICATION_20260922.json.','', 'Paper 1: CRLF working-copy digest and LF committed-content digest are distinct valid bindings; no paper edit is implied. Paper 3: clean compile is reported. Paper 2: two errors from line 653 are reported; its recovered PDF is not a clean rendering and must not circulate.','', 'The A25 notes are advisory evaluator evidence within their stated scope; supporting proofs still require the designated independent review. No evaluator result was rerun in this intake.')
WriteText "$out/NOTE_HASH_VERIFICATION_20260922.md" ($noteLines -join "`n")
$outcomes = @{
 a25_01='Scoped one-frame no-go; producer-only.'; a25_02='Typed criterion and scope analysis; producer-only.';
 a25_03='COMPLETE per final STATUS/manifest: outcome (3), joint rank-29 projection no-go; independent review pending.';
 a25_04='COMPLETE per STATUS: outcome (3), ten selected minors no-go; independent review pending.';
 a25_05='Outcome (3), structural reduction; containment/separation open. Overnight connectivity interruption attested by user; retain disclosure, no new timing gate.';
 b25_01='Paper 3 five-edit after-state; clean compile reported on matching source; review pending.';
 b25_02='HOLD FOR PRE-DELIVERY REPAIR: Paper 2 line 653 compile error; outcome (2), mathematical readiness blockers remain.';
 b25_03='Paper 1 readiness withdrawal and proposed attribution patch; patch NOT applied; paper unchanged; reported clean unsigned compile.';
 b25_04='Scoped component-family no-go; 2 wrapped pilots reported (first vacuous, second nonvacuous); review pending.';
 b25_05='Length restriction proof producer-only; equivariance no-go; B25-10 review required before C45 qualifier change.';
 b25_06='Partial boundary reduction, conditional premises named; G-A1 remains OPEN; review pending.'
}
$lines = @('# Batch 25 exact-path delivery proposal — 2026-09-22','','PROPOSAL ONLY — UNCOMMITTED / NOT RELEASED. No staging, commits, pushes, session launches, experiments, compiler runs, producer edits, or Git configuration changes were performed. This proposal updates the existing B25-12 live ledger under the userʼs direct coordinator instruction.','','## Verified inventory','','Eleven completed packets: 135 inventoried paths, of which 133 are proposed producer delivery paths and two are unchanged B25-03 bindings. All supplied payload hash/size checks pass. The JSON inventory binds raw SHA256, bytes, current filtered/raw Git object IDs, baseline content, ignore results, branch and HEAD. Full repository status snapshots also contain unrelated files; those are excluded from delivery.','','Each path below is relative to the explicitly stated absolute worktree. This is an exact list, not a directory glob. ADD_EXACT_PATH includes both new files and tracked after-states. Configuration changes described later are additional proposed paths.','')
foreach($p in $inventory.packets) {
 $lines += @("## $($p.slot.ToUpperInvariant())",'',"Worktree: ``$root/$($p.worktree)``", "Branch: ``$($p.branch)``; baseline/current HEAD: ``$($p.head)``.",'', $outcomes[$p.slot],'',"Manifest: ``$($p.manifest)``; raw SHA256 ``$($p.manifest_sha256)``.",'','| Exact relative path | Bytes | Raw SHA256 | Action |','|---|---:|---|---|')
 foreach($f in $p.files) { $lines += "| ``$($f.path)`` | $($f.bytes) | ``$($f.sha256_raw)`` | $($f.delivery_action) |" }
 $lines += ''
}
$lines += @('## Configuration changes proposed per branch','','Append only the following negation on each slotʼs own branch, after the broad PID ignore rule. Include that branchʼs `.gitignore` in its delivery. These are proposed edits, not applied. Only B25-04 currently has PID receipts; the other five negations implement the userʼs requested coverage.','','| Worktree (under repository root) | Exact config path | Line to append | Current config SHA256 |','|---|---|---|---|')
foreach($p in @($inventory.packets | Where-Object slot -like 'b25_*')) { $lines += "| ``$($p.worktree)`` | ``.gitignore`` | ``!results/logs/$($p.slot)_*.pid`` | ``$(Hash "$root/$($p.worktree)/.gitignore")`` |" }
$lines += @('','For byte preservation, append these exact-path attributes to `.gitattributes` in the indicated worktree; include that `.gitattributes` in its delivery. Existing raw bytes and producer manifests must remain unchanged. `-text` disables line-ending conversion; `whitespace=cr-at-eol` prevents CRLF provenance bytes being treated as whitespace defects. No broad renormalization.','')
foreach($group in @($inventory.packets | Group-Object worktree)) {
 $changed = @($group.Group.files | Where-Object { $_.filter_changes_bytes -and $_.delivery_action -eq 'ADD_EXACT_PATH' })
 if($changed.Count) { $lines += @("Worktree ``$root/$($group.Name)``; config ``.gitattributes``; current raw SHA256 ``$(Hash "$root/$($group.Name)/.gitattributes")``.",'','```gitattributes'); foreach($f in $changed) {$lines += "$($f.path) -text whitespace=cr-at-eol"}; $lines += @('```','') }
}
$lines += @('B25-03: do not stage the unchanged paper/det3-conductor.tex or README.md and do not change their attributes just to preserve a working-copy rendering. Their raw CRLF and committed LF hashes are separately bound. B25-05 and B25-06: current raw/filtered bytes agree; no new attributes are required by this observation. Recheck at actual delivery.','','Coordinator branch: also propose `.gitattributes` additions `docs/b25_12_ledger.md -text whitespace=cr-at-eol` and `results/b25_12/** -text whitespace=cr-at-eol`, and include `.gitattributes`. No coordinator PID negation is needed because no pilot ran.','','## Pre-delivery repair and evidence holds','','D5 — B25-02: source line 653 contains an optional-argument citation inside the optional theorem title. The integrator reports two parser errors from this line. Brace the citation as `{\cite[Thm.~3.1]{Dimca13}}` or move the provenance outside the optional header while retaining the proved-modulo qualification. No repair has been applied in this intake. Recompile, inspect the log and rendering, and require zero errors. Preserve the present failed-build binding as history; record new after-state hashes, diff and build receipts in a separately identified repair supplement or versioned manifest. Refresh the exact delivery list for any newly created repair artifacts before authorization. Do not silently overwrite a sealed manifest or claim its old hash binds repaired bytes. The listed B25-02 packet is complete as a producer record, but release-ready delivery is held.','','D6 — Three compiled-PDF digests in the integrator notes cannot be confirmed locally; build logs were not located either. Obtain matching artifacts or a new source-bound build receipt before claiming independently verified build evidence. Source hashes do match. Papers 1 and 3 have integrator-reported clean builds, not a coordinator build certification. Paper 2ʼs recovered PDF must not circulate.','','D7 — Independent acceptance remains pending. B25-10 and A25-10 stay WAITING for committed, hash-bound inputs; no launch is authorized here. Extend A25-10ʼs original input scope explicitly to A25-03/04/05 before any later launch. Keep C45ʼs (star) qualifier until review accepts B25-05, and do not infer the quartic 16-to-9 transfer from the cubic proof. Paper 2ʼs B17-01 closure dependency and B14/B16 decisions remain open. Paper 1ʼs attribution patch is unapplied and readiness remains withdrawn. G-A1 remains open.','','## Delivery procedure for a separately authorized future pass','','1. Recheck each branch HEAD, file hashes and exact status against the inventory; any drift requires reconciliation. Preserve the current proposal as the intake snapshot.','2. Apply only the proposed per-branch config edits, then confirm both B25-04 PID files are no longer ignored. Do not force-add around the rule defect.','3. Stage only the explicitly enumerated paths after authorization. Verify staged blob content bytes, sizes and SHA256 against raw bindings; raw-versus-filtered equality is mandatory for delivered manifest-bound payloads. Inspect config diffs separately. Preserve before/after bindings for tracked papers.','4. Deliver A25-01/02 before dependent A25-03/04, and those before A25-05, or in one explicitly scoped main-worktree delivery. Pin each producerʼs actual delivery commit for cross-branch reviewers; do not merge or cherry-pick unrelated work. B25-01/02 retain existing qualifiers while B25-05 awaits review.','5. Record real commit IDs only after authorized delivery; then update review input bindings and the live ledger. None exist for these packets yet.','','Exclude unrelated caches, old-session receipts, tool memory, other research continuations, all unlisted untracked files, and unavailable PDFs/logs. A directory-level add, add-all, or renormalization is outside this proposal.','','## Coordinator exact delivery paths','','Worktree: `'+$coord+'`; branch `b15-12-padding-orbit-bounds`; baseline HEAD `f55ed57f636e5ae6ea791f3238a66f9414008c90`.', '', 'The coordinator manifest hashes the following existing/new administrative artifacts, except itself; the proposed config edit is not yet hash-bound as an after-state.','')
$coordPaths = @('docs/b25_12_ledger.md','results/b25_12/TAKEOVER_RECEIPT_20260921T033154Z.md','results/b25_12/intake_20260922.ps1','results/b25_12/INTAKE_INVENTORY_20260922.json','results/b25_12/finish_intake_20260922.ps1','results/b25_12/NOTE_HASH_VERIFICATION_20260922.json','results/b25_12/NOTE_HASH_VERIFICATION_20260922.md','results/b25_12/DELIVERY_PROPOSAL_20260922.md','results/b25_12/COORDINATOR_MANIFEST_20260922.json')
foreach($s in $snapshots) { $coordPaths += $s.snapshot.Substring($coord.Length+1) }
foreach($path in $coordPaths) { $lines += "- ``$path``" }
$lines += '- `.gitattributes` — proposed configuration edit only, not applied.'
WriteText "$out/DELIVERY_PROPOSAL_20260922.md" ($lines -join "`n")
$ledgerPath = "$coord/docs/b25_12_ledger.md"
$append = @('','','## Coordinator reconciliation — 2026-09-22 (current authoritative snapshot)','','The user explicitly directed this coordinator intake using this existing live ledger. This dated reconciliation supersedes the older PREPARED/IN PROGRESS status observations above; historical entries are retained. No sessions launched, no Git mutation, no experiments.','','| Slot | Current state and limits |','|---|---|')
foreach($p in $inventory.packets) { $append += "| $($p.slot.ToUpperInvariant()) | LOCAL COMPLETE / UNCOMMITTED / NOT RELEASED. $($outcomes[$p.slot]) |" }
$append += @('','All eleven packets were intaken from disk and their manifests. All available payload hash and size bindings pass; all observed branch HEADs remain at recorded baselines. A25-03ʼs final STATUS outcome and final manifest establish local completion; A25-04 STATUS explicitly says COMPLETE. These are producer outcomes, not independent acceptance.','','The four integrator notes were intaken and preserved byte-for-byte. Full source digests match local raw files or recorded committed content. The three full PDF digests remain unverified because matching build artifacts were not located; no compiler or evaluator was run. Details: `results/b25_12/NOTE_HASH_VERIFICATION_20260922.md` and `.json`.','','D1–D4 are expanded by `results/b25_12/DELIVERY_PROPOSAL_20260922.md`: 133 exact producer delivery paths plus two unchanged B25-03 reference bindings; per-branch PID negations for b25_01_ through b25_06_; 24 delivered files need exact-path byte-preservation attributes. Two B25-04 PID receipts are currently ignored. Config edits are proposed only. The inventory includes exact current/baseline content bindings.','','D5 — PRE-DELIVERY REPAIR: B25-02 line 653, nested optional citation in theorem title. Two compile errors reported on exactly matched source. Brace citation or move provenance out of optional header, retain qualification, recompile to zero errors, and record fresh source/build bindings without destroying the original failed-state record. Not repaired here.','','D6 — Missing compiled-PDF/log artifacts: obtain matching evidence or source-bound rebuilt evidence before claiming coordinator-verified compilation. D7 — B25-10 and A25-10 remain WAITING for committed inputs; A25-10 needs explicit expanded A25-03/04/05 review scope. No mathematical claim labels upgraded.','','A25-05 timing disclosure retained. The user attributed the overnight interval to laptop internet loss and instructed that it be ignored; this intake records that attestation and does not create a new timing blocker.','','Compute lease observed now: '+$(if(Test-Path "$root/work/batch15/results/batch25_coordination/compute.lock"){'compute.lock PRESENT; untouched, no lease acquired by coordinator.'}else{'compute.lock absent; no recovery action, no lease acquired.'}), '', 'Coordinator files are bound by `results/b25_12/COORDINATOR_MANIFEST_20260922.json`. The delivery proposal is pending separate authorization; no staging, commit, push, launch, experiment, paper edit or publication occurred.')
$old = [IO.File]::ReadAllBytes($ledgerPath)
$addition = $utf8.GetBytes(($append -join "`n")+"`n")
$stream = [IO.File]::Open($ledgerPath,[IO.FileMode]::Append)
try {$stream.Write($addition,0,$addition.Length)} finally {$stream.Dispose()}
$records = @()
foreach($path in $coordPaths | Where-Object {$_ -ne 'results/b25_12/COORDINATOR_MANIFEST_20260922.json'}) {
 $full = "$coord/$path"; $records += [ordered]@{path=$path; bytes=(Get-Item -LiteralPath $full).Length; sha256=(Hash $full)}
}
WriteText "$out/COORDINATOR_MANIFEST_20260922.json" ([ordered]@{status='UNCOMMITTED / NOT RELEASED; administrative intake only'; created_utc=[DateTime]::UtcNow.ToString('s')+'Z'; self_hash='Excluded to avoid recursion'; files=$records} | ConvertTo-Json -Depth 8)
Write-Output "Completed: $($inventory.packets.Count) packets; $($files.Count) inventory paths; $($checks.Count) note hash citations; $(@($checks | Where-Object status -like 'UNVERIFIED*').Count) unverified artifact citations."
